@Test
public void test_patterMatching_misMatches() {
    // clearly invalid values don't match.
    String[] durations = new String[] { "9am", "-", "", "9-5", "9-10am", "9pm-6", // only 2 digits allowed
    "009AM-5AM", // space betweem am or pm are not allowed
    "9am-5p m", // if there is a : then minutes part must follow!
    "9:am-5:30pm", // Minutes part is limited to 2 digits
    "9:00am-5:300pm", // No space allowed around the :
    "9: 00am-5 :300pm" };
    check(durations, false);
}

