            try {
                byte[] seed = new byte[16];
                SECURE_RANDOM.nextBytes(seed);
                KeyVersion kv = kpExt.createKey("foo", seed, opt);
                kpExt.rollNewVersion(kv.getName());
                seed = new byte[16];
                SECURE_RANDOM.nextBytes(seed);
                kpExt.rollNewVersion(kv.getName(), seed);
                kpExt.deleteKey(kv.getName());
